-- 4. Check the register, A to Z
SELECT * FROM members ORDER BY nickname;

-- 5. How many in each club?
SELECT club, COUNT(*) AS total FROM members GROUP BY club;

signups = ["Coding", "Press", "Coding", "JETS", "Coding", "Press", "Coding"]
limit = 4

counts = {}
for club in signups:
    counts[club] = counts.get(club, 0) + 1

print("Club Report 📋")
for club, total in counts.items():
    if total >= limit:
        status = "FULL - join the waiting list"
    elif total == limit - 1:
        status = "Almost full - hurry!"
    else:
        status = "Open - welcome!"
    print(f"{club}: {total} members -> {status}")
